def longestKDistinct(s, k):
    from collections import defaultdict
    count = defaultdict(int)
    l = best = 0
    for r, ch in enumerate(s):
        count[ch] += 1
        while len(count) > k:
            count[s[l]] -= 1
            if count[s[l]] == 0:
                del count[s[l]]
            l += 1
        best = max(best, r - l + 1)
    return best

