    parts = data.split("\n")
    board = eval(parts[0].split("=", 1)[1].strip())
    words = eval(parts[1].split("=", 1)[1].strip())
    root = build_trie(words)
    m, n = len(board), len(board[0])
    result = []
    def dfs(i, j, node):
        if i < 0 or i >= m or j < 0 or j >= n:
            return
        c = board[i][j]
        if c not in node.children:
            return
        next_node = node.children[c]
        if next_node.word:
            result.append(next_node.word)
            next_node.word = None
        board[i][j] = '#'
        dfs(i + 1, j, next_node)
        dfs(i - 1, j, next_node)
        dfs(i, j + 1, next_node)
        dfs(i, j - 1, next_node)
        board[i][j] = c
        if not next_node.children:
            del node.children[c]
    for i in range(m):
        for j in range(n):
            dfs(i, j, root)
    print(result)

