class LRUCache:
    def __init__(self, cap):
        self.cap = cap
        self.cache = {}
        self.order = []
    def _touch(self, key):
        self.order.remove(key)
        self.order.append(key)
    def get(self, key):
        if key in self.cache:
            self._touch(key)
            return self.cache[key]
        return -1
    def put(self, key, value):
        if key in self.cache:
            self.cache[key] = value
            self._touch(key)
        else:
            if len(self.order) >= self.cap:
                lru = self.order.pop(0)
                del self.cache[lru]
            self.cache[key] = value
            self.order.append(key)
