def first_unique(nums):
    seen = set()
    for n in nums:
        if n in seen:
            return n
        seen.add(n)
    return -1

def max_product_pair(nums):
    nums = sorted(nums)
    return max(nums[0] * nums[1], nums[-1] * nums[-2])

def count_good_pairs(nums):
    count, freq = 0, {}
    for n in nums:
        count += freq.get(n, 0)
        freq[n] = freq.get(n, 0) + 1
    return count

def max_consecutive_ones(nums):
    best = cur = 0
    for n in nums:
        cur = cur + 1 if n else 0
        if cur > best:
            best = cur
    return best

def count_zero_triplets(nums):
    nums = sorted(nums)
    n = len(nums)
    res = 0
    for i in range(n):
        if i and nums[i] == nums[i - 1]:
            continue
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = nums[i] + nums[lo] + nums[hi]
            if s == 0:
                res += 1
                while lo < hi and nums[lo] == nums[lo + 1]:
                    lo += 1
                while lo < hi and nums[hi] == nums[hi - 1]:
                    hi -= 1
                lo += 1
                hi -= 1
            elif s < 0:
                lo += 1
            else:
                hi -= 1
    return res

def max_container_area(heights):
    lo, hi = 0, len(heights) - 1
    best = 0
    while lo < hi:
        best = max(best, min(heights[lo], heights[hi]) * (hi - lo))
        if heights[lo] < heights[hi]:
            lo += 1
        else:
            hi -= 1
    return best

def sort_colors(nums):
    nums[:] = sorted(nums)
    return nums

def trap_rain_water(heights):
    lo, hi = 0, len(heights) - 1
    lmax = rmax = 0
    water = 0
    while lo <= hi:
        if lmax <= rmax:
            if heights[lo] >= lmax:
                lmax = heights[lo]
            else:
                water += lmax - heights[lo]
            lo += 1
        else:
            if heights[hi] >= rmax:
                rmax = heights[hi]
            else:
                water += rmax - heights[hi]
            hi -= 1
    return water

def unique_occurrences(arr):
    from collections import Counter
    c = Counter(arr)
    return len(c.values()) == len(set(c.values()))

def first_unique_char(s):
    from collections import Counter
    c = Counter(s)
    for i, ch in enumerate(s):
        if c[ch] == 1:
            return i
    return -1

def reverse_vowels(s):
    vowels = set("aeiouAEIOU")
    arr = list(s)
    i, j = 0, len(arr) - 1
    while i < j:
        while i < j and arr[i] not in vowels:
            i += 1
        while i < j and arr[j] not in vowels:
            j -= 1
        arr[i], arr[j] = arr[j], arr[i]
        i += 1
        j -= 1
    return "".join(arr)

def run_length_compress(s):
    if not s:
        return ""
    out = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            out.append(s[i - 1] + str(count))
            count = 1
    out.append(s[-1] + str(count))
    return "".join(out)

def count_and_say(n):
    s = "1"
    for _ in range(n - 1):
        out = []
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            out.append(str(j - i) + s[i])
            i = j
        s = "".join(out)
    return s

def min_swaps_group_ones(nums):
    ones = nums.count(1)
    if ones <= 1:
        return 0
    cur = sum(nums[:ones])
    best = cur
    for i in range(ones, len(nums)):
        cur += nums[i] - nums[i - ones]
        best = max(best, cur)
    return ones - best

def shortest_substr_all_distinct(s):
    from collections import defaultdict
    need = set(s)
    if not need:
        return 0
    want = len(need)
    seen = defaultdict(int)
    have, left, best = 0, 0, len(s) + 1
    for right, ch in enumerate(s):
        seen[ch] += 1
        if seen[ch] == 1:
            have += 1
        while have == want:
            best = min(best, right - left + 1)
            lc = s[left]
            seen[lc] -= 1
            if seen[lc] == 0:
                have -= 1
            left += 1
    return best

def peak_index_mountain(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[mid + 1]:
            hi = mid
        else:
            lo = mid + 1
    return lo

