def allPathsSourceTarget(graph):
    n=len(graph);res=[]
    def dfs(u,path):
        if u==n-1: res.append(path[:]);return
        for v in graph[u]:
            path.append(v);dfs(v,path);path.pop()
    dfs(0,[0]);return res

from collections import deque
def alienOrder(words):
    adj={c:set() for w in words for c in w}
    indeg={c:0 for c in adj}
    for i in range(len(words)-1):
        w1,w2=words[i],words[i+1];found=False
        for c1,c2 in zip(w1,w2):
            if c1!=c2:
                if c2 not in adj[c1]: adj[c1].add(c2);indeg[c2]=indeg.get(c2,0)+1
                found=True;break
        if not found and len(w1)>len(w2): return ''
    q=deque([c for c in indeg if indeg[c]==0]);res=[]
    while q:
        c=q.popleft();res.append(c)
        for nei in adj[c]:
            indeg[nei]-=1
            if indeg[nei]==0: q.append(nei)
    return ''.join(res) if len(res)==len(adj) else ''

def maxSubArray(nums):
    max_sum=cur_sum=nums[0]
    for n in nums[1:]:
        cur_sum=max(n,cur_sum+n);max_sum=max(max_sum,cur_sum)
    return max_sum

def minPathSum(grid):
    m,n=len(grid),len(grid[0])
    for i in range(1,m): grid[i][0]+=grid[i-1][0]
    for j in range(1,n): grid[0][j]+=grid[0][j-1]
    for i in range(1,m):
        for j in range(1,n):
            grid[i][j]+=min(grid[i-1][j],grid[i][j-1])
    return grid[m-1][n-1]

def maxProfit(prices):
    min_price=float('inf');max_profit=0
    for p in prices:
        if p<min_price: min_price=p
        elif p-min_price>max_profit: max_profit=p-min_price
    return max_profit

def coinChange(coins,amount):
    dp=[float('inf')]*(amount+1);dp[0]=0
    for a in range(1,amount+1):
        for c in coins:
            if a>=c: dp[a]=min(dp[a],dp[a-c]+1)
    return -1 if dp[amount]==float('inf') else dp[amount]

def wordBreak(s,wordDict):
    words=set(wordDict);n=len(s);dp=[False]*(n+1);dp[0]=True
    for i in range(1,n+1):
        for j in range(i):
            if dp[j] and s[j:i] in words: dp[i]=True;break
    return dp[n]

def lengthOfLIS(nums):
    tails=[]
    for x in nums:
        i=0;j=len(tails)
        while i<j:
            m=(i+j)//2
            if tails[m]<x: i=m+1
            else: j=m
        if i==len(tails): tails.append(x)
        else: tails[i]=x
    return len(tails)

def maximalSquare(matrix):
    m,n=len(matrix),len(matrix[0])
    dp=[[0]*(n+1) for _ in range(m+1)];max_side=0
    for i in range(1,m+1):
        for j in range(1,n+1):
            if matrix[i-1][j-1]=='1':
                dp[i][j]=min(dp[i-1][j],dp[i][j-1],dp[i-1][j-1])+1
                max_side=max(max_side,dp[i][j])
    return max_side*max_side

def canPartition(nums):
    total=sum(nums)
    if total%2: return False
    target=total//2;dp=[False]*(target+1);dp[0]=True
    for n in nums:
        for s in range(target,n-1,-1):
            if dp[s-n]: dp[s]=True
    return dp[target]

def rob(nums):
    prev2,prev1=0,0
    for n in nums:
        cur=max(prev1,prev2+n);prev2=prev1;prev1=cur
    return prev1

def longestCommonSubsequence(text1,text2):
    m,n=len(text1),len(text2)
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(1,m+1):
        for j in range(1,n+1):
            if text1[i-1]==text2[j-1]: dp[i][j]=dp[i-1][j-1]+1
            else: dp[i][j]=max(dp[i-1][j],dp[i][j-1])
    return dp[m][n]

def minimumTotal(triangle):
    dp=triangle[-1][:]
    for i in range(len(triangle)-2,-1,-1):
        for j in range(len(triangle[i])):
            dp[j]=triangle[i][j]+min(dp[j],dp[j+1])
    return dp[0]

def isInterleave(s1,s2,s3):
    if len(s1)+len(s2)!=len(s3): return False
    m,n=len(s1),len(s2)
    dp=[[False]*(n+1) for _ in range(m+1)];dp[0][0]=True
    for i in range(1,m+1): dp[i][0]=dp[i-1][0] and s1[i-1]==s3[i-1]
    for j in range(1,n+1): dp[0][j]=dp[0][j-1] and s2[j-1]==s3[j-1]
    for i in range(1,m+1):
        for j in range(1,n+1):
            dp[i][j]=(dp[i-1][j] and s1[i-1]==s3[i+j-1]) or (dp[i][j-1] and s2[j-1]==s3[i+j-1])
    return dp[m][n]

def minDistance(word1,word2):
    m,n=len(word1),len(word2)
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1): dp[i][0]=i
    for j in range(n+1): dp[0][j]=j
    for i in range(1,m+1):
        for j in range(1,n+1):
            if word1[i-1]==word2[j-1]: dp[i][j]=dp[i-1][j-1]
            else: dp[i][j]=1+min(dp[i-1][j],dp[i][j-1],dp[i-1][j-1])
    return dp[m][n]

def numDistinct(s,t):
    m,n=len(s),len(t)
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1): dp[i][0]=1
    for i in range(1,m+1):
        for j in range(1,n+1):
            if s[i-1]==t[j-1]: dp[i][j]=dp[i-1][j-1]+dp[i-1][j]
            else: dp[i][j]=dp[i-1][j]
    return dp[m][n]

def numTrees(n):
    dp=[0]*(n+1);dp[0]=dp[1]=1
    for i in range(2,n+1):
        for j in range(1,i+1):
            dp[i]+=dp[j-1]*dp[i-j]
    return dp[n]

def combinationSum4(nums,target):
    dp=[0]*(target+1);dp[0]=1
    for t in range(1,target+1):
        for n in nums:
            if t>=n: dp[t]+=dp[t-n]
    return dp[target]

def maxCoins(nums):
    n=len(nums);nums=[1]+nums+[1]
    dp=[[0]*(n+2) for _ in range(n+2)]
    for length in range(1,n+1):
        for i in range(1,n-length+2):
            j=i+length-1
            for k in range(i,j+1):
                dp[i][j]=max(dp[i][j],dp[i][k-1]+dp[k+1][j]+nums[i-1]*nums[k]*nums[j+1])
    return dp[1][n]

def isMatch(s,p):
    m,n=len(s),len(p)
    dp=[[False]*(n+1) for _ in range(m+1)];dp[0][0]=True
    for j in range(2,n+1):
        if p[j-1]=='*': dp[0][j]=dp[0][j-2]
    for i in range(1,m+1):
        for j in range(1,n+1):
            if p[j-1]=='.' or p[j-1]==s[i-1]: dp[i][j]=dp[i-1][j-1]
            elif p[j-1]=='*':
                dp[i][j]=dp[i][j-2] or (dp[i-1][j] and (p[j-2]=='.' or p[j-2]==s[i-1]))
    return dp[m][n]

def shortestCommonSupersequence(s,t):
    m,n=len(s),len(t)
    dp=[[0]*(n+1) for _ in range(m+1)]
    for i in range(1,m+1):
        for j in range(1,n+1):
            if s[i-1]==t[j-1]: dp[i][j]=dp[i-1][j-1]+1
            else: dp[i][j]=max(dp[i-1][j],dp[i][j-1])
    i,j=m,n;res=[]
    while i>0 or j>0:
        if i==0: res.append(t[j-1]);j-=1
        elif j==0: res.append(s[i-1]);i-=1
        elif s[i-1]==t[j-1]: res.append(s[i-1]);i-=1;j-=1
        elif dp[i-1][j]>dp[i][j-1]: res.append(s[i-1]);i-=1
        else: res.append(t[j-1]);j-=1
    return ''.join(reversed(res))

def maxSizeSlices(slices):
    def helper(arr,k):
        n=len(arr);dp=[[0]*(k+1) for _ in range(n+1)]
        for i in range(1,n+1):
            for j in range(1,k+1):
                pick=arr[i-1]+(dp[i-2][j-1] if i>=2 else 0)
                skip=dp[i-1][j]
                dp[i][j]=max(pick,skip)
        return dp[n][k]
    k=len(slices)//3
    return max(helper(slices[1:],k),helper(slices[:-1],k))

def longestStrChain(words):
    words.sort(key=len);dp={}
    for w in words:
        dp[w]=1
        for i in range(len(w)):
            pred=w[:i]+w[i+1:]
            if pred in dp: dp[w]=max(dp[w],dp[pred]+1)
    return max(dp.values())
